package com.yourapp.drama.workflow;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.node.*; import com.yourapp.drama.persistence.*; import org.springframework.stereotype.Service; import java.util.*; import static com.yourapp.drama.persistence.ResourceKind.*; import static com.yourapp.drama.workflow.Documents.*;
@Service public class CharacterStateResolver { private final DocumentStore store; public CharacterStateResolver(DocumentStore store){this.store=store;} public ObjectNode resolve(String projectId,String characterId,double t){ObjectNode r=obj().put("characterId",characterId).put("storyTime",t);ObjectNode chosen=null;for(ObjectNode s:store.list(CHARACTER_STATE,projectId,characterId))if(active(s,t)&&(chosen==null||num(s,"validFromStoryTime")>num(chosen,"validFromStoryTime")))chosen=s;if(chosen!=null)for(String f:List.of("id","state","alive","currentLocation","currentGoal","physicalCondition","injuries","emotionalState","currentLookId","clothingState","makeupState","hairState","carriedProps","leftHandProp","rightHandProp","validFromStoryTime","validToStoryTime","sourceSceneId","sourceShotId"))if(chosen.has(f))r.set(f,chosen.get(f).deepCopy());return r;}private boolean active(JsonNode n,double t){return t>=num(n,"validFromStoryTime")&&(!n.has("validToStoryTime")||n.path("validToStoryTime").isNull()||t<num(n,"validToStoryTime"));}private double num(JsonNode n,String f){return n.path(f).isNumber()?n.path(f).asDouble():Double.NEGATIVE_INFINITY;}}
